from taf.cloud.cbam.exception import UnsupportedVimInfoType
from taf.cloud.cbam.schemas.schema_base import CbamSchema


class VimInfo(CbamSchema):
    def __init__(self, id, vim_info_type=None):
        self.id = id
        if vim_info_type is not None:
            VimInfoType.verify_vim_info_type(vim_info_type=vim_info_type)
            self.vim_info_type = vim_info_type
        else:
            self.vim_info_type = None

    @classmethod
    def from_response_dict(cls, resp_dict):
        vim_info_type = resp_dict["vimInfoType"]
        return VimInfoType.dispatch(vim_info_type, schema_version="3").from_response_dict(resp_dict)


class VimInfo3_3(VimInfo):
    @classmethod
    def from_response_dict(cls, resp_dict):
        vim_info_type = resp_dict["vimInfoType"]
        return VimInfoType.dispatch(vim_info_type, schema_version="3.3").from_response_dict(resp_dict)


class EndpointInfo(CbamSchema):
    def __init__(self, endpoint, trusted_certificates=None, skip_certificate_verification=None,
                 skip_certificate_hostname_check=None):
        self.endpoint = endpoint
        self.trusted_certificates = trusted_certificates
        self.skip_certificate_verification = skip_certificate_verification
        self.skip_certificate_hostname_check = skip_certificate_hostname_check

    @classmethod
    def from_response_dict(cls, resp_dict):
        return cls(
            endpoint=resp_dict["endpoint"],
            trusted_certificates=resp_dict.get("trustedCertificates", None),
            skip_certificate_verification=resp_dict.get("skipCertificateVerification", None),
            skip_certificate_hostname_check=resp_dict.get("skipCertificateHostnameCheck", None)
        )

    def as_dict(self):
        result = {'endpoint': self.endpoint}
        if self.trusted_certificates is not None:
            result['trustedCertificates'] = self.trusted_certificates
        if self.skip_certificate_verification is not None:
            result['skipCertificateVerification'] = self.skip_certificate_verification
        if self.skip_certificate_hostname_check is not None:
            result['skipCertificateHostnameCheck'] = self.skip_certificate_hostname_check
        return result


class OpenStackAccessInfoV2(CbamSchema):
    def __init__(self, region, tenant, username, password=None):
        self.password = password
        self.region = region
        self.tenant = tenant
        self.username = username

    @classmethod
    def from_response_dict(cls, resp_dict):
        return cls(
            password=resp_dict.get("password", None), tenant=resp_dict["tenant"], region=resp_dict["region"],
            username=resp_dict["username"]
        )

    def as_dict(self):
        result = {'region': self.region, 'tenant': self.tenant, 'username': self.username}
        if self.password is not None:
            result['password'] = self.password
        return result


