class OpenstackV2Info(VimInfo):
    def __init__(self, id=None, vim_info_type=None, interface_info=None, access_info=None):
        super(OpenstackV2Info, self).__init__(id=id,
                                              vim_info_type=vim_info_type)
        self.interface_info = interface_info
        self.access_info = access_info

    @classmethod
    def from_response_dict(cls, resp_dict):
        access_info = OpenStackAccessInfoV2.from_response_dict(resp_dict["accessInfo"])
        interface_info = EndpointInfo.from_response_dict(resp_dict["interfaceInfo"])
        return cls(
            id=resp_dict["id"], vim_info_type=resp_dict["vimInfoType"], interface_info=interface_info,
            access_info=access_info
        )

    def as_dict(self):
        result = {'id': self.id,
                  'vimInfoType': self.vim_info_type,
                  'interfaceInfo': self.interface_info.as_dict(),
                  'accessInfo': self.access_info.as_dict()}
        return result


