class VimInfoType(object):
    OPENSTACK_V2_INFO = 'OPENSTACK_V2_INFO'
    OPENSTACK_V3_INFO = 'OPENSTACK_V3_INFO'
    VMWARE_VCLOUD_INFO = 'VMWARE_VCLOUD_INFO'
    OTHER_VIM_INFO = 'OTHER_VIM_INFO'
    OPENSTACK_VIM_INFO = 'OpenStackVimInfo'

    supported_types = (
        OPENSTACK_V2_INFO, OPENSTACK_V3_INFO, VMWARE_VCLOUD_INFO,
        OTHER_VIM_INFO, OPENSTACK_VIM_INFO)

    dispatch_dict = {
        OPENSTACK_V2_INFO: {
            "3": OpenstackV2Info,
            "3.3": OpenstackV2Info
        },
        OPENSTACK_V3_INFO: {
            "3": OpenstackV3Info,
            "3.3": OpenstackV3_3Info
        },
        VMWARE_VCLOUD_INFO: {
            "3": VMwareVcloudInfo,
            "3.3": VMwareVcloudInfo
        },
        OPENSTACK_VIM_INFO: {
            "3": OpenstackVimInfo,
            "3.3": OpenstackVimInfo
        },
        OTHER_VIM_INFO: {
            "3": OtherVimInfo,
            "3.3": OtherVimInfo
        }
    }

    @classmethod
    def dispatch(cls, type_name, schema_version):
        cls.verify_vim_info_type(vim_info_type=type_name)
        return cls.dispatch_dict[type_name][schema_version]

    @classmethod
    def verify_vim_info_type(cls, vim_info_type):
        if vim_info_type not in cls.supported_types:
            raise UnsupportedVimInfoType("{} is an unsupported VIM info type.".format(vim_info_type))
